# ---------------------
# abstract signal types
# ---------------------
abstract type WTBasis end
const WT_LEVELS = Union{Int, Tuple{Int, Int}}
const SIGNAL_1D = Union{Vector{<:Number}, SubArray{<:Number,1}}
const SIGNAL_2D = Union{Matrix{<:Number}, SubArray{<:Number,2}}

"""
    WTOrthogonalBasis: Basis for an orthogonal wavelet transform.

    This structure represents an orthogonal DWT basis.
    Scaling and wavelet filters for the 1D and 2D case
    are stored. The length of the tap vector is
    additionally stored. Convenience constructors are
    provided.
"""
struct WTOrthogonalBasis{N, T<:Number} <: WTBasis
    # fields
    φ  :: SVector{N, T} # scaling filter
    ψ  :: SVector{N, T} # wavelet filter
    φφ :: SMatrix{N, N, T} # scaling filter
    φψ :: SMatrix{N, N, T} # scaling filter
    ψφ :: SMatrix{N, N, T} # wavelet filter
    ψψ :: SMatrix{N, N, T} # wavelet filter

    # convenience constructor 1: specified scaling/wavelet filters.
    """
        WTOrthogonalBasis(φ, ψ)
        
        Convenience constructor for WTOrthogonalBasis class.
        Takes scaling and wavelet filters for φ and ψ.
    """
    function WTOrthogonalBasis(φ :: SVector{N, T},
                               ψ :: SVector{N, T}) where {N, T <: AbstractFloat}

        # check that the transform specification is valid
        #  sum(ψ) ≈ 0             || error("WTOrthogonalBasis: ψ is not zero-mean.")
        #  length(φ) == length(ψ) || error("Basis is not orthogonal.")

        # construct the structure
        new{N, T}(
            φ / norm(φ),
            ψ / norm(ψ),
            φ * φ' / norm(φ * φ'),
            φ * ψ' / norm(φ * ψ'),
            ψ * φ' / norm(ψ * φ'),
            ψ * ψ' / norm(ψ * ψ'),
        )
    end

    # convenience 2: just the wavelet, let the code
    # derive an orthogonal scaling filter for you.
    """
        WTOrthogonalBasis(ψ)

        Convenience constructor for WTOrthogonalBasis. Determines
        scaling function by orthogonalisation.
    """
    function WTOrthogonalBasis(; φ :: Union{SVector{N,T}, Nothing} = nothing, 
                                 ψ :: Union{SVector{N,T}, Nothing} = nothing) where {N, T <: AbstractFloat}

        
        # sanity check
        (isnothing(φ) && isnothing(ψ)) && error("fuck you")
        ψ = isnothing(ψ) ? complement(φ) : ψ
        φ = isnothing(φ) ? complement(ψ) : φ

        WTOrthogonalBasis(φ, ψ)
    end
end

function to_blocks(v::AbstractArray{T,1}) where T <: Number
    blocks = ["▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"]
    r = range(minimum(v), maximum(v), 8)
    Float64(r.step) ≈ 0 && return blocks[4]^length(v)
    rc = collect(r)
    s = map(v) do sample
        tmp = abs.(rc .- sample)
        i = argmin(tmp)
        #  @info i
        blocks[i]
    end
    join(s)
end

function Base.show(io::IO, w::WTOrthogonalBasis{N,F}) where {N, F}
    print(io, styled"{bold:$N-tap Orthogonal Basis}: ",
              styled"φ {bold,blue:▕}$(to_blocks(w.φ)){bold,blue:▏},", styled"ψ {bold,blue:▕}$(to_blocks(w.ψ)){bold,blue:▏}")
end


